let maps = document.querySelectorAll("[data-cord1]")
if(maps.length > 0){
    // ymaps.ready(init);
}




function init2(map){
    maps.forEach(map=> {
        createMap(map)
    })

    function createMap(map){
        let cord = [+map.dataset.cord1, +map.dataset.cord2]

        let myMap = new ymaps.Map(map, {
            center: cord,
            zoom: +map.dataset.zoom,
            controls: []
        });

        myMap.behaviors.disable('scrollZoom');

        let placeMark = new ymaps.Placemark(cord, {
                balloonContentHeader: ``,
                balloonContentBody: `
                <div class="place-card">
                    <div class="office-card__items">
                        <div class="place-card__title">
                            Москва
                        </div>
                        <div class="place-card__desc">
                            АвтоФЕС
                        </div>
                        <div class="place-card__nav _flex">
                            <a href="">Подробнее</a>
                        </div>
                    </div>
                </div>
                `,
                balloonContentFooter: '',
                hintContent: '',
            },
            {
                iconLayout: 'default#image',
                iconImageHref: "img/marker.svg",
                iconImageSize: [48, 53],
                iconImageOffset: [-24, -26.5],
                hideIconOnBalloonOpen: false,
            }
        );
        myMap.geoObjects.add(placeMark);
    }
}

var getScrollBarSize = (function() {
    var el = window.document.createElement('textarea'), style = {
        'visibility': 'hidden', 'position': 'absolute', 'zIndex': '-2147483647',
        'top': '-1000px', 'left': '-1000px', 'width': '1000px', 'height': '1000px',
        'overflow': 'scroll', 'margin': '0', 'border': '0', 'padding': '0'
    }, support = el.clientWidth !== undefined && el.offsetWidth !== undefined;

    for (var key in style) {
        if (style.hasOwnProperty(key)) {
            el.style[key] = style[key];
        }
    }

    return function() {
        var size = null;
        if (support && window.document.body) {
            window.document.body.appendChild(el);
            size = [el.offsetWidth - el.clientWidth, el.offsetHeight - el.clientHeight];
            window.document.body.removeChild(el);
        }

        document.documentElement.style.setProperty('--scrollWidth', `${size[0]}px`);
        return size;
    };
})();


gsap.registerPlugin(ScrollTrigger);

function initProtect() {
    const section = document.querySelector('.protect');
    if (!section) return;

    const cards = gsap.utils.toArray('.protect-card', section);
    if (!cards.length) return;

    const LINE = '60%'; // линия на экране, при пересечении которой карточка становится активной

    let current = -1;
    const setActive = (index) => {
        if (index === current) return;
        current = index;
        cards.forEach((card, i) => card.classList.toggle('_active', i === index));
    };

    cards.forEach((card, i) => {
        ScrollTrigger.create({
            trigger: card,
            start: `top ${LINE}`,
            onEnter: () => setActive(i),                  // скролл вниз: верх карточки дошёл до линии
            onLeaveBack: () => setActive(i - 1),          // скролл вверх: вернулись выше карточки
        });
    });

    window.addEventListener('load', () => ScrollTrigger.refresh());
}

document.addEventListener('DOMContentLoaded', initProtect);

function initAnatomy() {
    const section = document.querySelector(".anatomy");
    if (!section) return;

    const move = section.querySelector(".anatomy__move");
    const inner = section.querySelector(".anatomy__inner");
    if (!move || !inner) return;

    // Шаги: на втором две карточки сразу
    const steps = [
        [".filter-info__item1"],
        [".filter-info__item2", ".filter-info__item2_b"],
        [".filter-info__item3"],
        [".filter-info__item4"],
        [".filter-info__item5"],
        [".filter-info__item6"],
    ].map((sels) => sels.map((s) => section.querySelector(s)).filter(Boolean));

    const lastCard = steps[steps.length - 1][0];

    const STEP = 500; // px прокрутки на один шаг
    const SHIFT_Y = 220; // насколько картинка уезжает вниз за всю анимацию, px
    const GAP_RIGHT = 0; // отступ последней карточки от правого края контейнера, px

    // Сдвиг влево считаем так, чтобы в конце карточка 06 встала
    // у правого края контейнера. Размер картинки не важен.
    const shiftX = () => {
        const currentX = gsap.getProperty(move, "x");
        const lastRight = lastCard.getBoundingClientRect().right - currentX;
        const innerRight = inner.getBoundingClientRect().right - GAP_RIGHT;
        return Math.min(0, innerRight - lastRight);
    };

    let current = -1;
    const setStep = (index) => {
        if (index === current) return;
        current = index;
        steps.forEach((items, i) =>
            items.forEach((el) => el.classList.toggle("_active", i === index)),
        );
    };

    const mm = gsap.matchMedia();

    // Только ПК, от 992px. Ниже — обычная вёрстка без анимации
    mm.add("(min-width: 992px)", () => {
        setStep(0);

        const tl = gsap.timeline({
            // карточки переключаем по прогрессу самой анимации, а не скролла,
            // поэтому они идут синхронно с картинкой даже со сглаживанием scrub
            onUpdate: () => {
                const index = Math.min(
                    steps.length - 1,
                    Math.floor(tl.progress() * steps.length),
                );
                setStep(index);
            },
            scrollTrigger: {
                trigger: section,
                start: "top -10% top",
                end: () => `+=${STEP * (steps.length - 1)}`,
                pin: true,
                pinSpacing: true, // родитель main.content во flex, без этого следующая секция наедет
                scrub: 1,
                anticipatePin: 1,
                invalidateOnRefresh: true,
            },
        });

        tl.fromTo(move, { x: 0, y: 0 }, { x: shiftX, y: SHIFT_Y, ease: "none" });

        // при уходе ниже 992px gsap сам снимет pin и сбросит transform, снимаем и классы
        return () => {
            current = -1;
            steps.flat().forEach((el) => el.classList.remove("_active"));
        };
    });

    window.addEventListener("load", () => ScrollTrigger.refresh());
}

// Мобилка и планшет, до 992px
function initAnatomyMob() {
    const section = document.querySelector(".anatomy");
    if (!section) return;

    const img = section.querySelector(".anatomy__img");
    if (!img) return;

    // Как на ПК, только второй шаг — одна карточка .filter-info__item-mob
    const cards = [
        ".filter-info__item1",
        ".filter-info__item-mob",
        ".filter-info__item3",
        ".filter-info__item4",
        ".filter-info__item5",
        ".filter-info__item6",
    ]
        .map((s) => section.querySelector(s))
        .filter(Boolean);
    if (!cards.length) return;

    const STEP = 70; // прокрутка на один шаг, % от высоты экрана
    const SHIFT_X = -90; // сдвиг картинки влево к концу, % от ширины самой картинки

    let current = -1;
    const setStep = (index) => {
        if (index === current) return;
        current = index;
        cards.forEach((card, i) => card.classList.toggle("_active", i === index));
    };

    const mm = gsap.matchMedia();

    mm.add("(max-width: 991.98px)", () => {
        setStep(0);

        const tl = gsap.timeline({
            onUpdate: () => {
                const index = Math.min(
                    cards.length - 1,
                    Math.floor(tl.progress() * cards.length),
                );
                setStep(index);
            },
            scrollTrigger: {
                trigger: section,
                start: "top top",
                end: () =>
                    `+=${(window.innerHeight * STEP * (cards.length - 1)) / 100}`,
                pin: true,
                pinSpacing: true,
                // pinType: "transform",
                scrub: 1,
                anticipatePin: 1,
                invalidateOnRefresh: true,
            },
        });

        tl.fromTo(img, { xPercent: 0 }, { xPercent: SHIFT_X, ease: "none" });

        return () => {
            current = -1;
            cards.forEach((card) => card.classList.remove("_active"));
        };
    });
}

document.addEventListener("DOMContentLoaded", () => {
    initAnatomy();
    initAnatomyMob();
});

$(".plug-parent__tab").click(function () {
    let parentBlock = $(this).parents(".plug-parent")
    let tabId = $(this).attr("data-tab")
    $(parentBlock).find(".plug-parent__tab").removeClass("_active")
    $(this).addClass("_active")
    $(parentBlock).find(".plug-card").removeClass("_active")
    $(parentBlock).addClass("_show-child")
    $(parentBlock).find(`.${tabId}`).addClass("_active")
})

window.addEventListener('DOMContentLoaded', () => {
    fix100vh();
    window.addEventListener('resize', () => {
        fix100vh();
        getScrollBarSize()
        setPlaceholders()
    })
    setPlaceholders()
    getScrollBarSize()

    $('input[type="tel"]').mask('+7 (999) 999-99-99', { autoclear: false }, { placeholder: '+7 (   )    -  -  ' });
    // $(".m-select select").niceSelect()
    // $(".m-select li").click(function (){
    //     $(this).parents(".m-select").addClass("_is-selected");
    // })

    $('.js-select2').each(function (){
        $(this).select2({
            placeholder: $(this).attr('placeholder'),
            maximumSelectionLength: 2,
            language: "ru",
            allowClear: true,
            dropdownAutoWidth: false,
            dropdownCssClass : $(this).attr('data-css-class'),
            language: {
                noResults: function(){
                    return "Ничего не найдено";
                }
            },
        });
    })


})

function fix100vh() {
    let vh = window.innerHeight * 0.01;
    document.documentElement.style.setProperty('--vh', `${vh}px`);
}

function setPlaceholders(){
    $("[data-placeholder]").each(function (){
        $(this).attr("placeholder", $(this).attr("data-placeholder"));

        if(window.innerWidth<576){
            $(this).attr("placeholder", $(this).attr("data-placeholder-mob"));
        }
    })
}

$("._go-to-filter").click(function (e) {
    $("html, body").animate({ scrollTop: 0 }, 10);
    if(window.innerWidth>992){
        $(".car-search").slideToggle();
    } else{
        $(".header").toggleClass("_open-form")
    }
})

